import{_ as a,o as i,c as r,ai as l}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"Python 面试 · 工程与依赖","description":"","frontmatter":{},"headers":[],"relativePath":"guide/python/engineering-interview.md","filePath":"guide/python/engineering-interview.md"}'),t={name:"guide/python/engineering-interview.md"};function n(o,e,d,h,s,c){return i(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="python-面试-·-工程与依赖" tabindex="-1">Python 面试 · 工程与依赖 <a class="header-anchor" href="#python-面试-·-工程与依赖" aria-label="Permalink to “Python 面试 · 工程与依赖”">​</a></h1><hr><h2 id="高频问法" tabindex="-1">高频问法 <a class="header-anchor" href="#高频问法" aria-label="Permalink to “高频问法”">​</a></h2><ol><li>虚拟环境为什么要用？</li><li><code>requirements.txt</code> 和锁版本？</li><li>异常怎么设计？裸 <code>except</code> 为什么不好？</li><li>日志怎么打？</li><li>配置和密钥怎么管理？</li><li>脚本怎么做成可重复运行（幂等）？</li></ol><hr><h2 id="口述参考" tabindex="-1">口述参考 <a class="header-anchor" href="#口述参考" aria-label="Permalink to “口述参考”">​</a></h2><h3 id="_1-虚拟环境" tabindex="-1">1）虚拟环境 <a class="header-anchor" href="#_1-虚拟环境" aria-label="Permalink to “1）虚拟环境”">​</a></h3><p>每个项目独立依赖，避免全局包污染、「这台机器能跑那台不行」。<br><code>python -m venv .venv</code> 然后激活再 pip 安装。</p><h3 id="_2-依赖冻结" tabindex="-1">2）依赖冻结 <a class="header-anchor" href="#_2-依赖冻结" aria-label="Permalink to “2）依赖冻结”">​</a></h3><ul><li>开发可 <code>requirements.txt</code> 列主依赖</li><li>协作/生产最好有<strong>锁文件</strong>（pip freeze、poetry.lock、uv.lock）保证版本一致</li><li>区分主依赖与开发依赖（pytest 等）</li></ul><h3 id="_3-异常" tabindex="-1">3）异常 <a class="header-anchor" href="#_3-异常" aria-label="Permalink to “3）异常”">​</a></h3><ul><li>捕获具体异常（<code>Timeout</code>、<code>HTTPError</code>），少用裸 <code>except:</code></li><li>失败要日志 + 明确退出码或返回值</li><li>不要吞掉异常假装成功</li></ul><h3 id="_4-日志" tabindex="-1">4）日志 <a class="header-anchor" href="#_4-日志" aria-label="Permalink to “4）日志”">​</a></h3><p><code>logging</code> 模块：级别、时间、模块名；生产打到文件/stdout 给采集。<br> 调试用 <code>print</code> 可以，交付脚本应换成 logger。</p><h3 id="_5-配置与密钥" tabindex="-1">5）配置与密钥 <a class="header-anchor" href="#_5-配置与密钥" aria-label="Permalink to “5）配置与密钥”">​</a></h3><ul><li>环境变量或本地未提交的 <code>.env</code>（记得 gitignore）</li><li>不同环境（本地/测试）配置分离</li><li>API Key、数据库密码不进仓库、不进日志</li></ul><h3 id="_6-幂等与可重跑" tabindex="-1">6）幂等与可重跑 <a class="header-anchor" href="#_6-幂等与可重跑" aria-label="Permalink to “6）幂等与可重跑”">​</a></h3><p>批处理脚本：用「已处理 id 表/文件」跳过；输出写临时文件再原子替换；支持 <code>--dry-run</code>。<br> 面试一句：<strong>脚本也要能失败重跑，不能半成功不可恢复。</strong></p><hr><h2 id="小checklist-口述收尾" tabindex="-1">小checklist（口述收尾） <a class="header-anchor" href="#小checklist-口述收尾" aria-label="Permalink to “小checklist（口述收尾）”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>venv ✅  依赖锁 ✅  timeout ✅  日志 ✅  密钥不进库 ✅  可重跑 ✅</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>',21)])])}const g=a(t,[["render",n]]);export{b as __pageData,g as default};
